html:
{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}
{% set company_address = None %}

{% if company %}
    {% set addresses = frappe.get_all("Address", 
        filters=[
            ["Dynamic Link", "link_doctype", "=", "Company"],
            ["Dynamic Link", "link_name", "=", company.name]
        ], 
        fields=["*"]) %}
    {% if addresses %}
        {% set company_address = addresses[0] %}
    {% endif %}
{% endif %}

<div class="print-container">
    <!-- Company Header -->
    <div class="company-header">
        <div class="company-info">
            <div class="company-name">{{ company.company_name if company else "Company Name" }}</div>
            {% if company_address %}
            <div class="company-address">
                {{ company_address.address_line1 or "" }}
                {% if company_address.address_line2 %}, {{ company_address.address_line2 }}{% endif %}
                {% if company_address.city %}, {{ company_address.city }}{% endif %}
                {% if company_address.state %}, {{ company_address.state }}{% endif %}
                {% if company_address.pincode %} - {{ company_address.pincode }}{% endif %}
                {% if company_address.country %}, {{ company_address.country }}{% endif %}
            </div>
            {% endif %}
            {% if company and (company.email or company.phone_no) %}
            <div class="company-contact">
                {% if company.email %}{{ company.email }}{% endif %}
                {% if company.email and company.phone_no %} • {% endif %}
                {% if company.phone_no %}{{ company.phone_no }}{% endif %}
            </div>
            {% endif %}
        </div>
        {% if company and company.logo %}
        <div class="company-logo">
            <img src="{{ company.logo }}" alt="Company Logo">
        </div>
        {% endif %}
    </div>

    <hr class="divider">

    <!-- Work Order Header -->
    <div class="header">
        <div>
            <h1>Work Order: <span>{{ doc.name }}</span></h1>
            <p><strong>Production Item:</strong> {{ doc.production_item or "-" }}</p>
            <p><strong>BOM:</strong> {{ doc.bom_no or "-" }}</p>
        </div>
        <div class="header-right">
            <p><strong>Status:</strong> {{ doc.workflow_state or "-" }}</p>
            <p><strong>Order Qty:</strong> {{ frappe.format_value(doc.qty, {"fieldtype": "Float"}) or "-" }}</p>
            <p><strong>Date:</strong> {{ frappe.format_date(frappe.utils.nowdate()) }}</p>
        </div>
    </div>

    <!-- Production Info -->
    <div class="info-grid">
        <div class="info-box">
            <h3>Planned</h3>
            <p><strong>Start:</strong> {{ frappe.format_date(doc.planned_start_date) if doc.planned_start_date else "-" }}</p>
            <p><strong>End:</strong> {{ frappe.format_date(doc.planned_end_date) if doc.planned_end_date else "-" }}</p>
        </div>
        <div class="info-box">
            <h3>Actual</h3>
            <p><strong>Start:</strong> {{ frappe.format_date(doc.actual_start_date) if doc.actual_start_date else "-" }}</p>
            <p><strong>End:</strong> {{ frappe.format_date(doc.actual_end_date) if doc.actual_end_date else "-" }}</p>
        </div>
    </div>

    <!-- Materials Table -->
    <h3 class="section-title">Required Materials</h3>
    <table class="table compact">
        <thead>
            <tr>
                <th>Item</th>
                <th>UOM</th>
                <th>Req. Qty</th>
                <th>Avail. Src</th>
                <th>Avail. WIP</th>
                <th>Rate</th>
                <th>Amt</th>
            </tr>
        </thead>
        <tbody>
            {% for item in doc.required_items %}
            <tr>
                <td>
                    <div class="item-code">{{ item.item_code or "-" }}</div>
                    <div class="item-name">{{ item.item_name or "" }}</div>
                </td>
                <td>{{ item.stock_uom or "-" }}</td>
                <td>{{ frappe.format_value(item.required_qty, {"fieldtype": "Float"}) or "-" }}</td>
                <td>{{ frappe.format_value(item.available_qty_at_source_warehouse, {"fieldtype": "Float"}) or "-" }}</td>
                <td>{{ frappe.format_value(item.available_qty_at_wip_warehouse, {"fieldtype": "Float"}) or "-" }}</td>
                <td>{{ frappe.format_value(item.rate, {"fieldtype": "Currency", "options": doc.currency}) or "-" }}</td>
                <td>{{ frappe.format_value(item.amount, {"fieldtype": "Currency", "options": doc.currency}) or "-" }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Footer -->
    <div class="print-footer">
        <p>Generated on: {{ frappe.format_date(frappe.utils.nowdate()) }}</p>
        <p>{{ doc.name }} | Production Work Order</p>
    </div>
</div>

<style>
body {
    font-family: "Inter", Arial, sans-serif;
    color: #222;
    line-height: 1.4;
    font-size: 11px;
    background: #fff;
    padding: 15px;
}

/* Company Header */
.company-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}
.company-name {
    font-size: 16px;
    font-weight: 700;
    color: #111;
}
.company-address, .company-contact {
    font-size: 10px;
    color: #555;
    margin-top: 2px;
}
.company-logo img {
    height: 40px;
    object-fit: contain;
}
.divider {
    border: 0;
    border-top: 1px solid #ddd;
    margin: 10px 0 12px;
}

/* Work Order Header */
.header {
    display: flex;
    justify-content: space-between;
    border-bottom: 1px solid #ccc;
    padding-bottom: 6px;
    margin-bottom: 10px;
}
.header h1 {
    font-size: 13px;
    margin: 0 0 4px;
    color: #222;
}
.header p {
    margin: 2px 0;
}
.header-right {
    text-align: right;
}

/* Info Section */
.info-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 10px;
}
.info-box {
    background: #fafafa;
    border: 1px solid #eee;
    padding: 8px;
    border-radius: 4px;
}
.info-box h3 {
    font-size: 11px;
    margin-bottom: 5px;
    border-bottom: 1px solid #ddd;
    padding-bottom: 3px;
}

/* Table */
.table {
    width: 100%;
    border-collapse: collapse;
}
.table th,
.table td {
    padding: 3px 5px;
    border-bottom: 1px solid #eee;
    text-align: left;
}
.table th {
    background: #f5f5f5;
    font-weight: 600;
}
.table.compact th,
.table.compact td {
    font-size: 10px;
}
.item-code {
    font-weight: 600;
}
.item-name {
    color: #666;
    font-size: 9px;
}

/* Footer */
.print-footer {
    margin-top: 10px;
    border-top: 1px solid #ddd;
    text-align: center;
    padding-top: 5px;
    color: #777;
    font-size: 10px;
}

/* Print Adjustments */
@media print {
    body {
        padding: 0;
        font-size: 10px;
    }
    .print-container {
        max-width: 100%;
        border: none;
    }
}
</style>
